let latest=null;
const $=id=>document.getElementById(id);
const cameras=[{id:'way/1340792417',name:'CAM-01 · рядом с Вебстером',occupied:Array(10).fill(true)},{id:'way/1221764205',name:'CAM-02 · рядом с Ильхомом',occupied:Array.from({length:10},(_,i)=>i<5)}];
export function countSpaces(occupied){return{capacity:occupied.length,occupied:occupied.filter(Boolean).length,free:occupied.filter(x=>!x).length};}
export function initParkingCameras(){let selected=cameras[0],recording=false;function publish(){const n=recording?{free:latest.free,capacity:latest.capacity}:countSpaces(selected.occupied);document.dispatchEvent(new CustomEvent('oqim-camera-demo',{detail:{id:selected.id,free:n.free,source:recording?'CV загруженной записи':'схема камеры',at:Date.now()}}));$('parkingCameraImpact').textContent=`${selected.name}: ${n.capacity} размеченных − ${n.capacity-n.free} занятых = ${n.free} свободных. ${n.free?'Парковка может попасть в рекомендации, если пешком не более выбранного лимита.':'Парковка исключается из рекомендаций свободных мест.'} Применено только в ДЕМО; это не актуальная занятость Ташкента.`;}
function render(){const c=$('parkingCameraCanvas').getContext('2d');c.fillStyle='#182934';c.fillRect(0,0,800,360);$('parkingCameraSpaces').replaceChildren();if(recording&&latest){const img=new Image();img.onload=()=>{if(!recording)return;c.drawImage(img,0,0,800,360);latest.spaces.forEach((r,i)=>{c.strokeStyle=latest.occupancy[i]?.occupied?'#f18181':'#70e4b7';c.lineWidth=3;c.strokeRect(r[0]*800,r[1]*360,r[2]*800,r[3]*360);c.fillStyle=c.strokeStyle;c.fillText(String(i+1),r[0]*800+5,r[1]*360+17);});};img.src=latest.frame;$('parkingCameraSource').textContent=`CV ЗАПИСИ · ${latest.capacity} мест · кадр ${latest.time.toFixed(1)} с. Связь с выбранной парковкой задана вами для демо, место съёмки не подтверждено.`;}else{$('parkingCameraSource').textContent='СХЕМА КАМЕРЫ · вымышленные места и занятость. Реальная камера по этому адресу не подключена.';selected.occupied.forEach((busy,i)=>{const x=30+(i%5)*154,y=25+Math.floor(i/5)*175;c.strokeStyle=busy?'#f18181':'#70e4b7';c.lineWidth=3;c.strokeRect(x,y,125,145);c.fillStyle=c.strokeStyle;c.font='16px sans-serif';c.fillText(`P${i+1} · ${busy?'занято':'свободно'}`,x+5,y+23);if(busy){c.fillStyle='#8198ac';c.fillRect(x+32,y+38,60,95);c.fillStyle='#233745';c.fillRect(x+37,y+51,50,22);c.fillRect(x+37,y+97,50,18);}const b=document.createElement('button');b.textContent=`P${i+1}: ${busy?'освободить':'занять'}`;b.onclick=()=>{selected.occupied[i]=!selected.occupied[i];render();publish();};$('parkingCameraSpaces').append(b);});}}
$('parkingCameraSelect').onchange=()=>{selected=cameras.find(x=>x.id===$('parkingCameraSelect').value);recording=false;render();$('parkingCameraImpact').textContent='Нажмите «Применить в демо парковки», чтобы пересчитать рекомендации.';};$('parkingCameraApply').onclick=publish;$('parkingCameraReset').onclick=()=>{recording=false;render();};$('parkingCameraCV').onclick=()=>{if(!latest)return;recording=true;render();publish();};document.addEventListener('oqim-parking-cv',e=>{latest=e.detail;$('parkingCameraCV').disabled=false;$('parkingCameraImpact').textContent='Получен результат анализа записи. Выберите парковку и нажмите «Использовать кадр CV».';});document.addEventListener('oqim-reset-camera-demo',()=>{cameras[0].occupied=Array(10).fill(true);cameras[1].occupied=Array.from({length:10},(_,i)=>i<5);recording=false;render();$('parkingCameraImpact').textContent='Демо сброшено: у Вебстера 0 свободных, у Ильхома 5.';});document.addEventListener('oqim-open-parking-camera',e=>{$('parkingCameraSelect').value=e.detail;selected=cameras.find(x=>x.id===e.detail)||cameras[0];recording=false;render();$('parkingCameraPanel').scrollIntoView({behavior:'smooth',block:'center'});});render();}
